function getEffectiveCss() {
    const candidates = [
        path.join(__dirname, 'antigravity-chat-rtl.css'),
        path.join(path.dirname(__dirname), 'src', 'antigravity-chat-rtl.css'),
        path.join(path.dirname(__dirname), 'antigravity-chat-rtl.css'),
    ];
    for (const p of candidates) {
        if (fs.existsSync(p)) {
            try { return fs.readFileSync(p, 'utf8'); } catch (e) {}
        }
    }
    return RTL_CSS;
}

function findAntigravityPath(customPath) {
    if (customPath) {
        let cp = path.resolve(customPath.trim().replace(/^"|"$/g, ''));
        for (const rel of ['resources/app.asar', 'Contents/Resources/app.asar', 'app.asar']) {
            if (fs.existsSync(path.join(cp, rel))) return cp;
        }
        if (fs.existsSync(cp) && cp.endsWith('app.asar')) {
            let parent = path.dirname(cp);
            if (path.basename(parent).toLowerCase() === 'resources') return path.dirname(parent);
            return parent;
        }
    }

    const candidates = [];

    // 1. Running processes
    try {
        if (process.platform === 'win32') {
            const psCmd = 'Get-Process Antigravity -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Path';
            const out = execSync(`powershell -NoProfile -Command "${psCmd}"`, { encoding: 'utf8', timeout: 3000 });
            for (const line of out.split(/\r?\n/)) {
                const p = line.trim();
                if (p && p.toLowerCase().endsWith('antigravity.exe') && fs.existsSync(p)) {
                    const d = path.dirname(p);
                    if (!candidates.includes(d)) candidates.push(d);
                }
            }
        } else if (process.platform === 'darwin') {
            const out = execSync('pgrep -fl Antigravity', { encoding: 'utf8', timeout: 3000 });
            for (const line of out.split(/\r?\n/)) {
                if (line.includes('.app')) {
                    const idx = line.indexOf('.app');
                    const appP = line.substring(0, idx + 4).split(' ').pop();
                    if (fs.existsSync(appP) && !candidates.includes(appP)) candidates.push(appP);
                }
            }
        } else {
            const out = execSync('pgrep -fl antigravity', { encoding: 'utf8', timeout: 3000 });
            for (const line of out.split(/\r?\n/)) {
                const parts = line.split(' ');
                if (parts.length >= 2 && fs.existsSync(parts[1])) {
                    const d = path.dirname(parts[1]);
                    if (!candidates.includes(d)) candidates.push(d);
                }
            }
        }
    } catch (e) {}

    // 2. Standard paths
    if (process.platform === 'win32') {
        const localAppData = process.env.LOCALAPPDATA || '';
        if (localAppData) {
            const stdPath = path.join(localAppData, 'Programs', 'antigravity');
            if (fs.existsSync(stdPath) && !candidates.includes(stdPath)) candidates.push(stdPath);
        }

        for (const envVar of ['ProgramFiles', 'ProgramFiles(x86)', 'ProgramW6432']) {
            const pf = process.env[envVar] || '';
            if (pf) {
                const p1 = path.join(pf, 'Antigravity');
                const p2 = path.join(pf, 'antigravity');
                if (fs.existsSync(p1) && !candidates.includes(p1)) candidates.push(p1);
                if (fs.existsSync(p2) && !candidates.includes(p2)) candidates.push(p2);
            }
        }

        const appData = process.env.APPDATA || '';
        if (appData) {
            const pRoam = path.join(appData, 'Programs', 'antigravity');
            if (fs.existsSync(pRoam) && !candidates.includes(pRoam)) candidates.push(pRoam);
        }
    } else if (process.platform === 'darwin') {
        const home = process.env.HOME || '';
        const macDirs = [
            '/Applications/Antigravity.app',
            path.join(home, 'Applications', 'Antigravity.app'),
            '/Applications/Google Antigravity.app',
            path.join(home, 'Applications', 'Google Antigravity.app')
        ];
        for (const md of macDirs) {
            if (fs.existsSync(md) && !candidates.includes(md)) candidates.push(md);
        }
    } else {
        const home = process.env.HOME || '';
        const linuxDirs = [
            '/opt/Antigravity',
            '/opt/antigravity',
            '/usr/lib/antigravity',
            '/usr/share/antigravity',
            path.join(home, '.local', 'share', 'programs', 'antigravity'),
            path.join(home, '.local', 'share', 'antigravity')
        ];
        for (const ld of linuxDirs) {
            if (fs.existsSync(ld) && !candidates.includes(ld)) candidates.push(ld);
        }
    }

    for (const c of candidates) {
        for (const sub of [
            path.join(c, 'resources', 'app.asar'),
            path.join(c, 'Contents', 'Resources', 'app.asar'),
            path.join(c, 'app.asar')
        ]) {
            if (fs.existsSync(sub)) return c;
        }
    }

    return null;
}

function isRunning() {
    try {
        if (process.platform === 'win32') {
            const out = execSync('tasklist /FI "IMAGENAME eq Antigravity.exe"', { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] });
            return out.toLowerCase().includes('antigravity.exe');
        } else {
            const out = execSync('pgrep -i antigravity', { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] });
            return out.trim().length > 0;
        }
    } catch (e) {
        return false;
    }
}

function sleepSync(ms) {
    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

function closeAntigravity() {
    console.log('[*] Closing running Antigravity processes...');
    try {
        if (process.platform === 'win32') {
            execSync('taskkill /F /IM Antigravity.exe /T', { stdio: 'ignore' });
        } else {
            execSync('pkill -f -i antigravity', { stdio: 'ignore' });
        }
        sleepSync(1500);
    } catch (e) {}
}

function sha256Blocks(buf, blockSize = 4 * 1024 * 1024) {
    const blocks = [];
    for (let i = 0; i < buf.length; i += blockSize) {
        const chunk = buf.subarray(i, i + blockSize);
        blocks.push(crypto.createHash('sha256').update(chunk).digest('hex'));
    }
    return {
        algorithm: 'SHA256',
        hash: crypto.createHash('sha256').update(buf).digest('hex'),
        blockSize: blockSize,
        blocks: blocks
    };
}

function patchAsar(inputAsar, outputAsar, replacements) {
    const fd = fs.openSync(inputAsar, 'r');
    const headerBuf = Buffer.alloc(16);
    fs.readSync(fd, headerBuf, 0, 16, 0);

    const magic = headerBuf.readUInt32LE(0);
    const jsonLen = headerBuf.readUInt32LE(12);

    const jsonBuf = Buffer.alloc(jsonLen);
    fs.readSync(fd, jsonBuf, 0, jsonLen, 16);
    const header = JSON.parse(jsonBuf.toString('utf8'));

    const padding = (4 - (jsonLen % 4)) % 4;
    const payloadStart = 16 + jsonLen + padding;

    const fileEntries = [];
    function traverse(curr, parts) {
        if (curr.files) {
            for (const name of Object.keys(curr.files)) {
                traverse(curr.files[name], parts.concat(name));
            }
        } else {
            fileEntries.push({ parts, node: curr });
        }
    }
    traverse(header, []);

    const newChunks = [];
    let currentOffset = 0;

    for (const item of fileEntries) {
        const pathStr = item.parts.join('/');
        if (item.node.unpacked) continue;

        let content;
        if (replacements[pathStr]) {
            content = Buffer.isBuffer(replacements[pathStr])
                ? replacements[pathStr]
                : Buffer.from(replacements[pathStr], 'utf8');
            console.log(`  [+] Updated in archive: ${pathStr} (${content.length.toLocaleString()} bytes)`);
        } else {
            const oldOffset = parseInt(item.node.offset, 10);
            const oldSize = item.node.size;
            content = Buffer.alloc(oldSize);
            fs.readSync(fd, content, 0, oldSize, payloadStart + oldOffset);
        }

        item.node.offset = currentOffset.toString();
        item.node.size = content.length;
        item.node.integrity = sha256Blocks(content);

        newChunks.push(content);
        currentOffset += content.length;
    }
    fs.closeSync(fd);

    const newJsonBuf = Buffer.from(JSON.stringify(header), 'utf8');
    const newJsonLen = newJsonBuf.length;
    const newPaddingLen = (4 - (newJsonLen % 4)) % 4;
    const newPadding = Buffer.alloc(newPaddingLen, 0);

    const newSizeHeader = newJsonLen + newPaddingLen + 4;
    const newSizeTotal = newSizeHeader + 4;

    const newHeaderPrefix = Buffer.alloc(16);
    newHeaderPrefix.writeUInt32LE(4, 0);
    newHeaderPrefix.writeUInt32LE(newSizeTotal, 4);
    newHeaderPrefix.writeUInt32LE(newSizeHeader, 8);
    newHeaderPrefix.writeUInt32LE(newJsonLen, 12);

    const outFd = fs.openSync(outputAsar, 'w');
    fs.writeSync(outFd, newHeaderPrefix);
    fs.writeSync(outFd, newJsonBuf);
    if (newPaddingLen > 0) fs.writeSync(outFd, newPadding);
    for (const c of newChunks) {
        fs.writeSync(outFd, c);
    }
    fs.closeSync(outFd);
}

function extractFromAsar(asarPath, targetRelPath) {
    const fd = fs.openSync(asarPath, 'r');
    const headerBuf = Buffer.alloc(16);
    fs.readSync(fd, headerBuf, 0, 16, 0);
    const jsonLen = headerBuf.readUInt32LE(12);
    const jsonBuf = Buffer.alloc(jsonLen);
    fs.readSync(fd, jsonBuf, 0, jsonLen, 16);
    const header = JSON.parse(jsonBuf.toString('utf8'));
    const padding = (4 - (jsonLen % 4)) % 4;
    const payloadStart = 16 + jsonLen + padding;

    let curr = header;
    for (const p of targetRelPath.split('/')) {
        if (curr.files && curr.files[p]) {
            curr = curr.files[p];
        } else {
            fs.closeSync(fd);
            return null;
        }
    }
    const offset = parseInt(curr.offset, 10);
    const size = curr.size;
    const buf = Buffer.alloc(size);
    fs.readSync(fd, buf, 0, size, payloadStart + offset);
    fs.closeSync(fd);
    return buf.toString('utf8');
}

function getAsarMetadata(asarPath) {
    if (!asarPath || !fs.existsSync(asarPath)) return null;
    try {
        const mtime = fs.statSync(asarPath).mtimeMs;
        let versionStr = '0.0.0';
        try {
            const pkgStr = extractFromAsar(asarPath, 'package.json');
            if (pkgStr) {
                const pkg = JSON.parse(pkgStr);
                if (pkg.version) versionStr = pkg.version;
            }
        } catch (e) {}

        const vParts = [];
        const parts = versionStr.split(/[-+.]/);
        for (const part of parts) {
            if (/^\d+$/.test(part)) {
                vParts.push(parseInt(part, 10));
            } else {
                break;
            }
        }
        while (vParts.length < 3) vParts.push(0);

        let isPatched = false;
        try {
            const preloadStr = extractFromAsar(asarPath, 'dist/preload.js');
            isPatched = Boolean(preloadStr && preloadStr.includes('__ANTIGRAVITY_RTL_INJECTED__'));
        } catch (e) {}

        return {
            versionStr,
            versionParts: vParts,
            isPatched,
            mtime
        };
    } catch (e) {
        return null;
    }
}

function compareVersions(partsA, partsB) {
    const len = Math.max(partsA.length, partsB.length);
    for (let i = 0; i < len; i++) {
        const a = partsA[i] || 0;
        const b = partsB[i] || 0;
        if (a > b) return 1;
        if (a < b) return -1;
    }
    return 0;
}

function setupShortcuts(targetDir, launcherPath) {
    if (process.platform !== 'win32') return;
    const norm = (targetDir || '').toLowerCase().replace(/\\/g, '/');
    if (process.env.PYTEST_CURRENT_TEST || norm.includes('tmp') || norm.includes('temp') || norm.includes('mock')) {
        return;
    }

    const destLauncher = path.join(targetDir, 'AntigravityLauncher.exe');
    try {
        fs.copyFileSync(launcherPath, destLauncher);
    } catch(e) {}
    const targetExe = fs.existsSync(destLauncher) ? destLauncher : launcherPath;
    const iconSource = path.join(targetDir, 'Antigravity.exe');
    const psCode = `
    $wsh = New-Object -ComObject WScript.Shell
    $paths = @(
        [System.IO.Path]::Combine([System.Environment]::GetFolderPath('Desktop'), 'Antigravity.lnk'),
        [System.IO.Path]::Combine([System.Environment]::GetFolderPath('CommonDesktop'), 'Antigravity.lnk'),
        [System.IO.Path]::Combine([System.Environment]::GetFolderPath('StartMenu'), 'Programs', 'Antigravity.lnk'),
        [System.IO.Path]::Combine([System.Environment]::GetFolderPath('CommonStartMenu'), 'Programs', 'Antigravity.lnk')
    )
    $found = $false
    foreach ($p in $paths) {
        if (Test-Path $p) {
            $sc = $wsh.CreateShortcut($p)
            $sc.TargetPath = '${targetExe.replace(/'/g, "''")}'
            $sc.IconLocation = '${iconSource.replace(/'/g, "''")},0'
            $sc.WorkingDirectory = '${targetDir.replace(/'/g, "''")}'
            $sc.Save()
            $found = $true
        }
    }
    if (-not $found) {
        $desktopP = [System.IO.Path]::Combine([System.Environment]::GetFolderPath('Desktop'), 'Antigravity.lnk')
        $sc = $wsh.CreateShortcut($desktopP)
        $sc.TargetPath = '${targetExe.replace(/'/g, "''")}'
        $sc.IconLocation = '${iconSource.replace(/'/g, "''")},0'
        $sc.WorkingDirectory = '${targetDir.replace(/'/g, "''")}'
        $sc.Save()
    }
    `;
    try {
        execSync(`powershell -NoProfile -Command "${psCode.replace(/\r?\n/g, ' ')}"`, { stdio: 'ignore' });
        console.log('  [✓] Auto-Shield launcher installed & shortcuts protected.');
    } catch(e) {}
}

